#include <optional>
#include <string>

struct Version { long long major; long long minor; long long patch; std::string pre; };

static bool parseNumber(const std::string& s, long long& out)
{
    if (s.empty() || s.size() > 15) return false;
    if (s.size() > 1 && s[0] == '0') return false;       // no leading zeros
    out = 0;
    for (const char c : s)
    {
        if (c < '0' || c > '9') return false;
        out = out * 10 + (c - '0');
    }
    return true;
}

std::optional<Version> parseVersion(const std::string& text)
{
    std::string core{ text };
    std::string pre;
    const auto dash{ text.find('-') };
    if (dash != std::string::npos)
    {
        core = text.substr(0, dash);
        pre = text.substr(dash + 1);
        if (pre.empty()) return std::nullopt;
    }
    const auto d1{ core.find('.') };
    if (d1 == std::string::npos) return std::nullopt;
    const auto d2{ core.find('.', d1 + 1) };
    if (d2 == std::string::npos || core.find('.', d2 + 1) != std::string::npos) return std::nullopt;

    Version v{ 0, 0, 0, pre };
    if (!parseNumber(core.substr(0, d1), v.major)) return std::nullopt;
    if (!parseNumber(core.substr(d1 + 1, d2 - d1 - 1), v.minor)) return std::nullopt;
    if (!parseNumber(core.substr(d2 + 1), v.patch)) return std::nullopt;
    return v;
}

int compareVersions(const Version& a, const Version& b)
{
    if (a.major != b.major) return a.major < b.major ? -1 : 1;
    if (a.minor != b.minor) return a.minor < b.minor ? -1 : 1;
    if (a.patch != b.patch) return a.patch < b.patch ? -1 : 1;
    if (a.pre.empty() != b.pre.empty()) return a.pre.empty() ? 1 : -1;   // a pre-release is lower
    if (a.pre != b.pre) return a.pre < b.pre ? -1 : 1;
    return 0;
}

std::string bump(const Version& v, const std::string& part)
{
    Version n{ v.major, v.minor, v.patch, "" };
    if (part == "major") n = { v.major + 1, 0, 0, "" };
    else if (part == "minor") n = { v.major, v.minor + 1, 0, "" };
    else if (part == "patch") n = { v.major, v.minor, v.patch + 1, "" };
    return std::to_string(n.major) + "." + std::to_string(n.minor) + "." + std::to_string(n.patch);
}

unitTests:
Version V(const char* s) { return *parseVersion(s); }
TEST("parse") { const auto v{ parseVersion("1.4.2") }; CHECK(v.has_value()); CHECK_EQ(v->major, 1LL); CHECK_EQ(v->minor, 4LL); CHECK_EQ(v->patch, 2LL); CHECK(v->pre.empty()); CHECK_EQ(parseVersion("2.0.0-beta.1")->pre, std::string("beta.1")); }
TEST("reject bad versions") { CHECK(!parseVersion("1.4").has_value()); CHECK(!parseVersion("1.4.2.0").has_value()); CHECK(!parseVersion("1.04.2").has_value()); CHECK(!parseVersion("1.x.2").has_value()); CHECK(!parseVersion("1.4.2-").has_value()); CHECK(!parseVersion("").has_value()); CHECK(!parseVersion("1..2").has_value()); CHECK(parseVersion("0.0.0").has_value()); }
TEST("numeric comparison") { CHECK(compareVersions(V("1.10.0"), V("1.9.0")) > 0); CHECK(compareVersions(V("1.4.2"), V("1.4.2")) == 0); CHECK(compareVersions(V("0.9.9"), V("1.0.0")) < 0); }
TEST("pre-releases come first") { CHECK(compareVersions(V("2.0.0-beta.1"), V("2.0.0")) < 0); CHECK(compareVersions(V("2.0.0"), V("2.0.0-rc.1")) > 0); CHECK(compareVersions(V("2.0.0-alpha"), V("2.0.0-beta")) < 0); CHECK(compareVersions(V("2.0.0-beta"), V("1.9.9")) > 0); }
TEST("bump") { CHECK_EQ(bump(V("1.4.2"), "major"), std::string("2.0.0")); CHECK_EQ(bump(V("1.4.2"), "minor"), std::string("1.5.0")); CHECK_EQ(bump(V("1.4.2"), "patch"), std::string("1.4.3")); CHECK_EQ(bump(V("2.0.0-rc.1"), "patch"), std::string("2.0.1")); }

